const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const env = typeof $env === 'object' && $env ? $env : {};
const sourcePayload = $json.source_payload_json ?? {};
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Directed Item did not atomically claim a valid content_id.');
}
if (!title) {
  throw new Error('Fetch Next Directed Item did not return title.');
}
const narrationScript = String($json.narration_script ?? '').trim();
if (!narrationScript) {
  throw new Error('Fetch Next Directed Item did not return narration_script.');
}
const targetDurationSeconds = Number($json.target_duration_seconds ?? 45);
if (!Number.isFinite(targetDurationSeconds) || targetDurationSeconds <= 0) {
  throw new Error('target_duration_seconds must be a positive number.');
}
const scriptSceneGuidanceJson = Array.isArray($json.script_scene_guidance_json) ? $json.script_scene_guidance_json : [];
const creativeDefaults = sourcePayload.creative_defaults && typeof sourcePayload.creative_defaults === 'object'
  ? sourcePayload.creative_defaults
  : {};
const brandTone = String(env.STORYBOARD_BRAND_TONE || creativeDefaults.tone || env.STUDIO_BRAND_TONE || 'cinematic, concise, credible').trim() || 'cinematic, concise, credible';
const visualStyleRules = String(env.STORYBOARD_VISUAL_STYLE_RULES || 'dark, atmospheric, documentary-realistic, moody lighting, strong focal point, no visible text').trim() || 'dark, atmospheric, documentary-realistic, moody lighting, strong focal point, no visible text';
const subtitleStyleRules = String(env.STORYBOARD_SUBTITLE_STYLE_RULES || 'short lines, centered safe zone, high contrast, mobile readable').trim() || 'short lines, centered safe zone, high contrast, mobile readable';
const directorJson = $json.director_json && typeof $json.director_json === 'object' ? $json.director_json : {};
const directorPlanJson = Object.keys(directorJson).length > 0 ? JSON.stringify(directorJson, null, 2) : '';
const directorVoiceRole = String(directorJson.voice_role ?? '').trim();
const directorGlobalVisualStyle = String(directorJson.global_visual_style ?? '').trim();
const directorVisualStrategy = String(directorJson.visual_strategy ?? '').trim();
const directorGlobalPacing = String(directorJson.global_pacing ?? '').trim();
const directorGlobalMusicDirection = String(directorJson.global_music_direction ?? '').trim();
const promptPayload = {
  content_id: contentId,
  title,
  target_duration_seconds: targetDurationSeconds,
  script_scene_guidance_json: scriptSceneGuidanceJson,
  status_after_success: 'storyboard_complete',
  prompt_template_data: {
    title,
    category: String($json.category ?? 'general').trim() || 'general',
    target_duration_seconds: String(targetDurationSeconds),
    narration_script: narrationScript,
    script_scene_guidance_json: JSON.stringify(scriptSceneGuidanceJson, null, 2),
    brand_tone: brandTone,
    visual_style_rules: visualStyleRules,
    subtitle_style_rules: subtitleStyleRules,
    creative_defaults: creativeDefaults,
    creative_defaults_json: Object.keys(creativeDefaults).length > 0 ? JSON.stringify(creativeDefaults, null, 2) : '{}',
    director_json: directorJson,
    director_contract_json: directorJson,
    director_plan_json: directorPlanJson,
    director_voice_role: directorVoiceRole,
    director_global_visual_style: directorGlobalVisualStyle,
    director_visual_strategy: directorVisualStrategy,
    director_global_pacing: directorGlobalPacing,
    director_global_music_direction: directorGlobalMusicDirection,
  },
};
return [{
  json: {
    ...promptPayload,
    prompt_payload_base64: Buffer.from(JSON.stringify(promptPayload), 'utf8').toString('base64')
  }
}];

const stdout = String($json.stdout ?? '').trim();
if (!stdout) {
  throw new Error('Storyboard model adapter returned no stdout.');
}
let parsed;
try {
  parsed = JSON.parse(stdout);
} catch (error) {
  throw new Error('Storyboard model adapter returned invalid JSON: ' + error.message);
}
if (!parsed.content_id || !parsed.storyboard_response) {
  throw new Error('Storyboard model adapter did not provide the expected structured response.');
}
return [{ json: parsed }];

const response = $json.storyboard_response ?? {};
if (!$json.content_id) {
  throw new Error('Storyboard model adapter did not provide content_id.');
}
if (!Array.isArray(response.storyboard_json) || response.storyboard_json.length < 2 || response.storyboard_json.length > 16) {
  throw new Error('Storyboard model adapter must produce 2 to 16 storyboard scenes (1 title card + up to 15 content scenes).');
}
if (!Array.isArray(response.subtitle_lines_json) || response.subtitle_lines_json.length === 0) {
  throw new Error('Storyboard model adapter did not produce subtitle_lines_json.');
}
const storyboardJson = response.storyboard_json.map((scene, index) => ({
  scene_number: Number(scene?.scene_number ?? index + 1),
  duration_seconds: Number(scene?.duration_seconds ?? 0),
  narration_text: String(scene?.narration_text ?? '').trim(),
  dialogue_lines: Array.isArray(scene?.dialogue_lines) ? scene.dialogue_lines.map((line) => String(line ?? '').trim()).filter(Boolean) : [String(scene?.narration_text ?? '').trim()].filter(Boolean),
  tts_instructions: String(scene?.tts_instructions ?? '').trim(),
  visual_prompt: String(scene?.visual_prompt ?? '').trim(),
  asset_type: String(scene?.asset_type ?? '').trim(),
  transition: String(scene?.transition ?? '').trim(),
  mood: String(scene?.mood ?? '').trim(),
  music_cue: String(scene?.music_cue ?? '').trim(),
  is_face_image: Boolean(scene?.is_face_image),
  face_image_title: String(scene?.face_image_title ?? '').trim()
}));
if (storyboardJson.some((scene) => !Number.isInteger(scene.scene_number) || scene.scene_number < 1 || !Number.isFinite(scene.duration_seconds) || scene.duration_seconds <= 0 || (!scene.narration_text && !scene.is_face_image) || (!scene.dialogue_lines.length && !scene.is_face_image) || (!scene.tts_instructions && !scene.is_face_image) || !scene.visual_prompt || !['image', 'video'].includes(scene.asset_type) || !scene.transition || !scene.mood || !scene.music_cue)) {
  throw new Error('storyboard_json contains invalid scene data.');
}
const firstScene = storyboardJson[0];
if (!firstScene?.is_face_image || !firstScene.face_image_title) {
  throw new Error('storyboard_json scene 1 must be the face image and include face_image_title.');
}
const firstTitleWords = firstScene.face_image_title.split(/\s+/).filter(Boolean);
if (firstTitleWords.length < 2 || firstTitleWords.length > 5) {
  throw new Error('storyboard_json scene 1 face_image_title must be 2 to 5 words.');
}
if (firstScene.duration_seconds > 4.25) {
  throw new Error('storyboard_json scene 1 title card must be 4 seconds or shorter.');
}
const scriptSceneGuidanceJson = Array.isArray($json.script_scene_guidance_json) ? $json.script_scene_guidance_json : [];
const subtitleLines = response.subtitle_lines_json.map((line, index) => ({
  scene_number: Number(line?.scene_number ?? index + 1),
  text: String(line?.text ?? '').trim()
}));
if (subtitleLines.some((line) => !Number.isInteger(line.scene_number) || line.scene_number < 1 || !line.text)) {
  throw new Error('subtitle_lines_json contains invalid subtitle data.');
}
const renderManifestSeedJson = response.render_manifest_seed_json ?? {};
renderManifestSeedJson.subtitles = { ...(renderManifestSeedJson.subtitles ?? {}), enabled: false };
if (!renderManifestSeedJson.output || !Array.isArray(renderManifestSeedJson.timeline) || !renderManifestSeedJson.subtitles) {
  throw new Error('render_manifest_seed_json is missing output, timeline, or subtitles.');
}
return [{
  json: {
    content_id: $json.content_id,
    status_after_success: $json.status_after_success,
    storyboard_json: storyboardJson,
    cover_prompt: String(response.cover_prompt ?? '').trim(),
    subtitle_lines_json: subtitleLines,
    style_notes: String(response.style_notes ?? '').trim() + '\\n\\nVisual style summary: ' + String(response.visual_style_summary ?? '').trim() + '\\nModel: ' + String($json.generation_model ?? '').trim(),
    render_manifest_seed_json: renderManifestSeedJson,
    generation_model: String($json.generation_model ?? '').trim(),
    cost: $json.cost ?? {},
    raw_storyboard_json: {
      provider: String($json.generation_provider ?? $json.llm_provider ?? 'openai').trim(),
      generation_model: String($json.generation_model ?? '').trim(),
      provider_metadata: $json.provider_metadata ?? {},
      script_scene_guidance_json: scriptSceneGuidanceJson,
      parsed_response: response
    }
  }
}];

const cost_json_sql = JSON.stringify($json.cost ?? {}).replaceAll("'", "''");
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error(`Prepare Storyboard SQL Values received an invalid content_id: ${contentId || '<empty>'}.`);
}
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    storyboard_json_sql: JSON.stringify($json.storyboard_json ?? []).replaceAll("'", "''"),
    cover_prompt_sql: String($json.cover_prompt ?? '').replaceAll("'", "''"),
    subtitle_lines_json_sql: JSON.stringify($json.subtitle_lines_json ?? []).replaceAll("'", "''"),
    style_notes_sql: String($json.style_notes ?? '').replaceAll("'", "''"),
    render_manifest_seed_json_sql: JSON.stringify($json.render_manifest_seed_json ?? {}).replaceAll("'", "''"),
    scene_count_sql: Array.isArray($json.storyboard_json) ? $json.storyboard_json.length : 0,
    generation_model_sql: String($json.generation_model ?? '').replaceAll("'", "''"),
    cost_json_sql
  }
}];
